package com.company.platform.commerce.infrastructure.persistence;
import com.company.platform.commerce.domain.cart.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class JdbcCartRepository implements CartRepository { private final JdbcTemplate jdbc; private final CartItemRepository items; public JdbcCartRepository(JdbcTemplate jdbc,CartItemRepository items){this.jdbc=jdbc;this.items=items;}
 public Cart save(Cart c){jdbc.update("INSERT INTO carts(id,tenant_id,customer_id,store_id,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET status=?,updated_at=?",c.id(),c.tenantId(),c.customerId(),c.storeId(),c.status().name(),java.sql.Timestamp.from(c.createdAt()),java.sql.Timestamp.from(c.updatedAt()),c.status().name(),java.sql.Timestamp.from(c.updatedAt()));for(var i:c.items())items.save(c.tenantId(),i);return c;}
 private Cart map(java.sql.ResultSet r,int n)throws java.sql.SQLException{UUID id=(UUID)r.getObject("id"),t=(UUID)r.getObject("tenant_id");return Cart.rehydrate(id,t,(UUID)r.getObject("customer_id"),(UUID)r.getObject("store_id"),CartStatus.valueOf(r.getString("status")),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant(),items.findAllByTenantIdAndCartId(t,id));}
 public Optional<Cart> findByTenantIdAndId(UUID t,UUID id){return jdbc.query("SELECT * FROM carts WHERE tenant_id=? AND id=?",this::map,t,id).stream().findFirst();} public Optional<Cart> findByTenantIdAndCustomerId(UUID t,UUID c){return jdbc.query("SELECT * FROM carts WHERE tenant_id=? AND customer_id=? AND status='ACTIVE' ORDER BY created_at DESC",this::map,t,c).stream().findFirst();}
}
